// Shared pixel-airport life: air traffic and crowds drawn on a <canvas>.
// Used by the playable game on the main page (game.js) and by the scene
// banners on the subpages (mountScene below). Art: images/pixel/, generated by
// tools/pixel/scenes.py. All coordinates are art pixels.

window.Airport = (() => {
  const PIXEL = "images/pixel/";
  const reduceMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const rand = (min, max) => min + Math.random() * (max - min);
  const pick = (n) => Math.floor(Math.random() * n);

  // traffic.png: 4 nose-up pitch angles (cols) x [3 liveries x 4 gear positions] (rows),
  // 56x28 cells. Row = livery * 4 + gear step (0 down, 1 three-quarters, 2 a quarter, 3 up).
  // In a cell the wheels sit on row 23, so a plane rolling on a runway whose
  // wheel line is at y uses rollY = y - 23.
  const PLANE_W = 56;
  const PLANE_H = 28;

  function loadImages(names) {
    const img = {};
    return Promise.all(names.map((name) => new Promise((resolve, reject) => {
      const image = new Image();
      image.onload = () => { img[name] = image; resolve(); };
      image.onerror = reject;
      image.src = `${PIXEL}${name}.png`;
    }))).then(() => img);
  }

  // A view is { ctx, cam, viewW }: what part of the art the canvas shows.
  function sprite(view, image, col, fw, fh, x, y, flip, row = 0) {
    const dx = Math.round(x - view.cam);
    if (dx < -fw || dx > view.viewW) return;
    const { ctx } = view;
    if (flip) {
      ctx.save();
      ctx.translate(dx + fw, 0);
      ctx.scale(-1, 1);
      ctx.drawImage(image, col * fw, row * fh, fw, fh, 0, Math.round(y), fw, fh);
      ctx.restore();
    } else {
      ctx.drawImage(image, col * fw, row * fh, fw, fh, dx, Math.round(y), fw, fh);
    }
  }

  function pixel(view, x, y, colour) {
    const dx = Math.round(x - view.cam);
    if (dx < 0 || dx >= view.viewW) return;
    view.ctx.fillStyle = colour;
    view.ctx.fillRect(dx, Math.round(y), 1, 1);
  }

  // Gear: 1 = down, 0 = up. Shown as the nearest of the four drawn positions.
  const GEAR_TIME = 1.2;
  const gearStep = (gear) => Math.round((1 - gear) * 3);
  const planeRow = (p) => p.livery * 4 + gearStep(p.gear);

  const blinkOn = (period = 1000) => reduceMotion || Math.floor(performance.now() / (period / 2)) % 2 === 0;

  // Air traffic ------------------------------------------------------------
  // mode "airport": take-offs and landings on a runway (rollY = cell top while rolling).
  // mode "overflight": planes crossing the sky at altitude (for the window scene).
  // taxiY: optional plane taxiing slowly along an apron.
  function createTraffic({ mode = "airport", rollY = 75, taxiY = null, levelW = 720 }) {
    const planes = [];
    const stats = { takeoffs: 0, landings: 0, overflights: 0 };
    const taxi = taxiY === null ? null : { x: rand(0, levelW), y: taxiY, v: -10, livery: 1, gear: 1 };
    let next = 1.5;

    function spawn(view, kind) {
      const dir = Math.random() < 0.5 ? 1 : -1;
      const p = { dir, x: dir > 0 ? view.cam - PLANE_W : view.cam + view.viewW, livery: pick(3), pitch: 0 };
      if (mode === "overflight") {
        Object.assign(p, { kind: "overflight", phase: "cruise", y: rand(14, 52), v: rand(30, 45), pitch: pick(2), gear: 0 });
      } else if ((kind || (Math.random() < 0.5 ? "departure" : "arrival")) === "departure") {
        Object.assign(p, { kind: "departure", phase: "roll", y: rollY, v: 22, gear: 1, airborne: 0 });
      } else {
        // Glide slope chosen so touchdown lands a little past the middle of the view.
        const glide = 0.09;
        const distance = view.viewW * 0.55 + PLANE_W;
        // Arrivals come in gear up and lower it from halfway down the approach.
        const y = rollY - glide * distance;
        Object.assign(p, { kind: "arrival", phase: "approach", y, startY: y, v: 55, glide, pitch: 1, gear: 0 });
      }
      planes.push(p);
    }

    function step(p, dt) {
      if (p.kind === "departure") {
        if (p.phase === "roll") {
          p.v += 9 * dt;
          if (p.v > 48) p.phase = "climb";
        } else {
          // Rotate through 4, 8 and 12 degrees, climbing faster as the nose comes up.
          p.v = Math.min(70, p.v + 6 * dt);
          p.climb = Math.min(3, (p.climb || 0) + dt * 2.5);
          p.pitch = Math.floor(p.climb);
          p.y -= p.v * 0.1 * p.climb * dt;
          // Retract the gear shortly after lift-off.
          p.airborne += dt;
          if (p.airborne > 0.6) p.gear = Math.max(0, p.gear - dt / GEAR_TIME);
        }
      } else if (p.phase === "approach") {
        p.y += p.v * p.glide * dt;
        if (p.y - p.startY >= (rollY - p.startY) / 2) p.gear = Math.min(1, p.gear + dt / GEAR_TIME);
        if (p.y >= rollY) {
          p.y = rollY;
          p.touchdownGear = p.gear;
          p.phase = "rollout";
          p.pitch = 0;
          stats.landings += 1;
          next = rand(3, 8);
        }
      } else if (p.phase === "rollout") {
        // Slow down, then turn off the runway onto a taxiway behind the apron.
        p.v = Math.max(24, p.v - 14 * dt);
        if (p.v <= 24) p.phase = "exit";
      } else if (p.phase === "exit") {
        p.y += 5 * dt;
      }
      p.x += p.dir * p.v * dt;
    }

    function update(dt, view) {
      // One movement at a time. A landed plane that is rolling out or turning off
      // doesn't block the next arrival; a departure waits until the runway is clear.
      next -= dt;
      const busy = planes.some((p) => p.phase !== "rollout" && p.phase !== "exit");
      const runwayFree = !planes.some((p) => p.phase === "rollout");
      if (next <= 0 && !busy) spawn(view, runwayFree ? null : "arrival");

      for (let i = planes.length - 1; i >= 0; i--) {
        const p = planes[i];
        step(p, dt);
        const hidden = p.y < -PLANE_H || p.y > rollY + 16;
        const gone = hidden || p.x < view.cam - PLANE_W * 2 || p.x > view.cam + view.viewW + PLANE_W;
        if (!gone) continue;
        planes.splice(i, 1);
        if (p.kind === "departure") stats.takeoffs += 1;
        if (p.kind === "overflight") stats.overflights += 1;
        if (p.kind !== "arrival") next = rand(3, 8);
      }

      if (taxi) {
        taxi.x += taxi.v * dt;
        if (taxi.x < -PLANE_W) taxi.x = levelW;
      }
    }

    // Reduced motion: a still picture, placed inside the current view.
    function freeze(view) {
      const at = (f) => view.cam + view.viewW * f;
      if (mode === "overflight") {
        planes.push({ kind: "overflight", phase: "cruise", dir: 1, x: at(0.6), y: 30, v: 0, livery: 0, pitch: 1, gear: 0 });
        return;
      }
      planes.push(
        { kind: "departure", phase: "climb", dir: 1, x: at(0.15), y: rollY - 27, v: 0, livery: 0, pitch: 3, gear: 0 },
        { kind: "arrival", phase: "approach", dir: -1, x: at(0.7), y: rollY - 17, v: 0, livery: 1, pitch: 1, gear: 1 },
      );
    }

    function drawPlanes(view, img) {
      planes.forEach((p) => {
        sprite(view, img.traffic, p.pitch, PLANE_W, PLANE_H, p.x, p.y, p.dir < 0, planeRow(p));
        const lx = (cx) => p.x + (p.dir > 0 ? cx : PLANE_W - 1 - cx);
        const on = blinkOn();
        if (on) pixel(view, lx(30), p.y + 11, "#ff3b30");
        if (p.kind === "arrival" && p.phase === "approach" && !on) pixel(view, lx(50), p.y + 15, "#fff7d6");
      });
    }

    function drawTaxi(view, img) {
      if (taxi) sprite(view, img.traffic, 0, PLANE_W, PLANE_H, taxi.x, taxi.y, taxi.v < 0, planeRow(taxi));
    }

    return { planes, stats, taxi, update, freeze, drawPlanes, drawTaxi };
  }

  // For tests: "kind:phase:x,y:gear step[:touchdown gear step]".
  function describePlane(p) {
    const td = p.touchdownGear === undefined ? "" : `:td${gearStep(p.touchdownGear)}`;
    return `${p.kind}:${p.phase}:${Math.round(p.x)},${Math.round(p.y)}:g${gearStep(p.gear)}${td}`;
  }

  // Crowds -----------------------------------------------------------------
  // sheet: a 2-column sprite sheet of 14x20 people (crowd, crowd-dark or crew).
  // standers: [{x, feet, row, flip}], walkers: count + lanes (feet y values).
  // groups: people who walk together in step, e.g. an airline crew:
  //   [{ rows: [0, 1, 2], x, feet, v, gap }] (gap = spacing between members).
  function createCrowd({ sheet, rows, standers = [], walkers = 0, lanes = [], speed = [9, 18], minX = 0, maxX = 720, rowsFor = null, groups = [] }) {
    const people = [
      ...standers.map((s) => ({ v: 0, row: 0, ...s })),
      ...Array.from({ length: walkers }, (_, i) => ({
        x: rand(minX, maxX),
        feet: lanes[i % lanes.length],
        v: (i % 2 ? -1 : 1) * rand(...speed),
        row: rowsFor ? rowsFor[i % rowsFor.length] : (i + 2) % rows,
        phase: rand(0, 1000),
      })),
      // Group members share speed and step phase, spaced `gap` apart behind the leader.
      ...groups.flatMap((g) => {
        const phase = rand(0, 1000);
        return g.rows.map((row, i) => ({ x: g.x - Math.sign(g.v) * i * g.gap, feet: g.feet, v: g.v, row, phase }));
      }),
    ];

    function update(dt) {
      const now = performance.now();
      people.forEach((p) => {
        if (!p.v) return;
        p.x += p.v * dt;
        if (p.x > maxX + 20) p.x = minX - 20;
        if (p.x < minX - 20) p.x = maxX + 20;
        p.frame = Math.floor((now + p.phase) / 300) % 2;
      });
    }

    // Returns drawables so callers can depth-sort people with other sprites.
    function cast(view, img) {
      return people.map((p) => ({
        feet: p.feet,
        draw: () => sprite(view, img[sheet], p.frame ?? 1, 14, 20, p.x, p.feet - 20, p.v < 0 || p.flip, p.row),
      }));
    }

    function draw(view, img) {
      const list = cast(view, img);
      list.sort((a, b) => a.feet - b.feet);
      list.forEach((c) => c.draw());
    }

    return { people, update, cast, draw };
  }

  // Pilot page stand: a full turnaround ----------------------------------
  // parked -> tug-in -> pushback -> tug-off -> start -> taxi-out -> gap -> taxi-in -> shutdown -> parked.
  // stand-plane.png: 3 liveries (rows) of 170x52. tug.png sits at (TUG_DX, TUG_DY) from the
  // plane when hooked up. marshaller.png: 20x24 frames (0 wands up, 1 wands out, 2 arms down).
  const TUG_DX = 138;
  const TUG_DY = 36;
  const PUSH_DISTANCE = 70;

  function createStand({ x: standX, y, marshalX, marshalFeet }) {
    const s = { phase: "parked", t: 0, x: standX, v: 0, tugX: null, hooked: false, livery: 0, cycles: 0 };
    const go = (phase) => { s.phase = phase; s.t = 0; };

    function update(dt, view) {
      s.t += dt;
      const right = view.cam + view.viewW;
      switch (s.phase) {
        case "parked":
          if (s.t >= 6) { s.tugX = right + 4; go("tug-in"); }
          break;
        case "tug-in":
          s.tugX = Math.max(s.x + TUG_DX, s.tugX - 45 * dt);
          if (s.tugX === s.x + TUG_DX) { s.hooked = true; go("pushback"); }
          break;
        case "pushback": {
          // Ease in and out over 9s.
          const p = Math.min(1, s.t / 9);
          s.x = standX - PUSH_DISTANCE * (1 - Math.cos(Math.PI * p)) / 2;
          s.tugX = s.x + TUG_DX;
          if (p >= 1) { s.hooked = false; go("tug-off"); }
          break;
        }
        case "tug-off":
          s.tugX += 45 * dt;
          if (s.tugX > right + 4) { s.tugX = null; go("start"); }
          break;
        case "start":
          if (s.t >= 3) { s.v = 0; go("taxi-out"); }
          break;
        case "taxi-out":
          s.v = Math.min(34, s.v + 7 * dt);
          s.x += s.v * dt;
          if (s.x > right + 10) go("gap");
          break;
        case "gap":
          if (s.t >= 4) {
            s.livery = (s.livery + 1 + pick(2)) % 3;
            s.x = view.cam - 172;
            go("taxi-in");
          }
          break;
        case "taxi-in": {
          const left = standX - s.x;
          s.v = Math.max(3, Math.min(32, left * 0.6));
          s.x = Math.min(standX, s.x + s.v * dt);
          if (s.x === standX) { s.cycles += 1; go("shutdown"); }
          break;
        }
        case "shutdown":
          if (s.t >= 2) go("parked");
          break;
        default:
          break;
      }
    }

    // Reduced motion: the familiar still picture, tug hooked up at the stand.
    function freeze() {
      s.phase = "pushback";
      s.hooked = true;
      s.tugX = standX + TUG_DX;
    }

    const lit = (...phases) => phases.includes(s.phase);

    function draw(view, img) {
      if (s.phase !== "gap") {
        sprite(view, img["stand-plane"], 0, 170, 52, s.x, y, false, s.livery);
        const at = (px, py, colour) => pixel(view, s.x + px, y + py, colour);
        if (lit("pushback", "tug-off", "start", "taxi-out", "taxi-in") && blinkOn(1000)) at(78, 25, "#ff3b30");
        if (lit("start", "taxi-out", "taxi-in") && (reduceMotion || performance.now() % 1200 < 120)) at(17, 5, "#ffffff");
        if (lit("taxi-out", "taxi-in")) { at(131, 40, "#fff7d6"); at(132, 40, "#fff7d6"); }
        if (lit("start", "taxi-out") && !reduceMotion) {
          for (let i = 0; i < 4; i++) {
            if (Math.random() < 0.5) at(72 + pick(6), 41 + pick(4), "rgba(220,226,236,0.55)");
          }
        }
      }
      if (s.tugX !== null) sprite(view, img.tug, 0, 30, 15, s.tugX, y + TUG_DY, false);

      // Marshaller: guides the plane in, waves it off, otherwise stands with arms down.
      const now = performance.now();
      let frame = 2;
      if (!reduceMotion && lit("taxi-in")) frame = Math.floor(now / 450) % 2;
      if (!reduceMotion && lit("tug-off", "start")) frame = Math.floor(now / 300) % 2 === 0 ? 1 : 2;
      sprite(view, img.marshaller, frame, 20, 24, marshalX, marshalFeet - 24, true);
    }

    return { state: s, update, freeze, draw };
  }

  // Speech bubbles ---------------------------------------------------------
  // Every few seconds someone on screen says a short line in a pixel bubble.
  // Bubbles are HTML over the canvas (crisp text), decorative and hidden from
  // screen readers.

  const LINES = {
    travellers: [
      "Is gate D1 this way?", "I hope my bag made it.", "Window seat, please!", "Two hours early. Nailed it.",
      "Wait, which terminal?", "Did I leave the stove on?", "Duty free, here I come!", "Boarding pass... boarding pass...",
    ],
    kids: ["Mom! A plane!", "Are we there yet?", "I'm gonna be a pilot!", "Can I sit by the window?"],
    pilots: ["Clear skies tonight.", "Coffee first, then preflight.", "Nice cap, Captain!", "Smooth landing, I promise.", "Checklist complete."],
    attendants: ["Welcome aboard!", "Seatbelts on, smiles on.", "Bags in the overhead, please.", "Exits are here, here and there.", "Cabin crew, arm the doors."],
    devs: [
      "It works on my machine.", "Did you just push to main?", "Delayed: waiting on code review.", "Boarding group: JavaScript.",
      "Loading... 99%", "Who wrote this CSS?", "Merge conflict at 30,000 ft.", "Turn it off and on again?",
    ],
    photographers: ["Golden hour in 3, 2, 1...", "Shoot in RAW!", "Hold still... got it.", "That sky though.", "Long exposure: nobody move.", "One more shot, I promise."],
    groundCrew: ["Bags loaded!", "Fuel's topped up.", "Mind the jet blast!", "Ramp is clear.", "Cargo door closed."],
    spotters: ["Is that a 777?!", "Got the shot!", "Wait for the rotate...", "Registration noted.", "Hear that engine spool!"],
    marshaller: {
      parked: "Chocks in, engines off.",
      "tug-in": "Tug's on the way.",
      pushback: "Clear to push!",
      "tug-off": "Tow bar off. Have a good one!",
      start: "Engines starting!",
      "taxi-out": "Have a great flight!",
      gap: "Next one's coming in.",
      "taxi-in": "Left a bit... more... STOP!",
      shutdown: "Welcome in!",
    },
  };

  // speakers(): candidates as [{ person: {x, feet}, h, lines: [...] or () => [...] }].
  function createChatter({ host, canvas, speakers, every = [3.5, 7], hold = 3.2 }) {
    const bubble = document.createElement("p");
    bubble.className = "bubble";
    bubble.setAttribute("aria-hidden", "true");
    bubble.hidden = true;
    host.append(bubble);

    let timer = 1.5;
    let current = null;
    const recent = [];

    const onScreen = (p, view) => p.x > view.cam + 6 && p.x + 14 < view.cam + view.viewW - 6;

    function hide() {
      bubble.hidden = true;
      current = null;
      timer = rand(...every);
    }

    // Keep the bubble inside the scene; the tail still points at the speaker.
    function place(view, scale) {
      const { person, h } = current;
      const target = canvas.offsetLeft + (person.x + 8 - view.cam) * scale;
      const half = bubble.offsetWidth / 2;
      const left = Math.min(host.clientWidth - half - 4, Math.max(half + 4, target));
      bubble.style.left = `${Math.round(left)}px`;
      bubble.style.top = `${Math.round((person.feet - h - 3) * scale)}px`;
      bubble.style.setProperty("--tail", `${Math.round(target - left)}px`);
    }

    function say(view, scale) {
      const options = speakers().filter((s) => onScreen(s.person, view));
      if (!options.length) {
        timer = 1;
        return;
      }
      const speaker = options[pick(options.length)];
      const pool = typeof speaker.lines === "function" ? speaker.lines() : speaker.lines;
      const fresh = pool.filter((l) => !recent.includes(l));
      const from = fresh.length ? fresh : pool;
      const line = from[pick(from.length)];
      recent.push(line);
      if (recent.length > 6) recent.shift();
      bubble.textContent = line;
      bubble.hidden = false;
      current = { ...speaker, line };
      timer = hold;
      place(view, scale);
    }

    // active = false hides the bubble (e.g. the game's title screen or a dialog).
    function update(dt, view, scale, active = true) {
      if (!active) {
        if (current) hide();
        return;
      }
      timer -= dt;
      if (current) {
        if (timer <= 0 || !onScreen(current.person, view)) hide();
        else place(view, scale);
      } else if (timer <= 0) {
        say(view, scale);
      }
    }

    return { update, get line() { return current ? current.line : null; } };
  }

  // Subpage scenes ---------------------------------------------------------
  // Each scene is 720x168 art pixels, drawn in layers. The static CSS-sprite
  // version in the HTML stays as the no-JS fallback and is hidden once live.

  const SCENES = {
    gate: {
      images: ["gate-sky", "gate-apron", "gate-front", "traffic", "crowd"],
      traffic: { rollY: 75 },
      crowd: {
        sheet: "crowd", rows: 8, walkers: 5, lanes: [121, 123, 125],
        standers: [{ x: 380, feet: 121, row: 4 }, { x: 395, feet: 122, row: 1 }, { x: 452, feet: 124, row: 3, flip: true }],
      },
      layers: ["gate-sky", "@planes", "gate-apron", "@beacon:262,71", "gate-front", "@laptop:431,96,11,5", "@crowd"],
      talk: ({ crowd }) => crowd.people.map((p) => ({ person: p, h: 20, lines: LINES.devs })),
    },
    window: {
      images: ["window-front", "traffic", "crowd-dark", "photographer"],
      transparent: true,
      traffic: { mode: "overflight" },
      crowd: {
        sheet: "crowd-dark", rows: 8, walkers: 4, lanes: [131, 133], speed: [8, 14],
        standers: [{ x: 470, feet: 131, row: 2 }, { x: 612, feet: 132, row: 5, flip: true }],
      },
      layers: ["@planes", "window-front", "@photographer:290,58", "@crowd"],
      talk: ({ crowd }) => [
        { person: { x: 284, feet: 120 }, h: 62, lines: LINES.photographers },
        ...crowd.people.map((p) => ({ person: p, h: 20, lines: LINES.photographers })),
      ],
    },
    apron: {
      images: ["apron-sky", "apron-apron", "apron-front", "traffic", "crew", "stand-plane", "tug", "marshaller"],
      traffic: { rollY: 101 },
      crowd: {
        sheet: "crew", rows: 3, walkers: 3, lanes: [140, 144, 148], speed: [5, 9], rowsFor: [0, 1, 0],
      },
      stand: { x: 300, y: 96, marshalX: 478, marshalFeet: 146 },
      spotters: [{ x: 96, feet: 167, row: 2 }, { x: 584, feet: 166, row: 2 }, { x: 660, feet: 167, row: 2, flip: true }],
      layers: ["apron-sky", "@planes", "apron-apron", "@stand", "@crowd", "apron-front", "@spotters", "@beacon:519,13"],
      talk: ({ crowd, spotters, stand }) => [
        { person: { x: 481, feet: 146 }, h: 24, lines: () => [LINES.marshaller[stand.state.phase]] },
        ...crowd.people.map((p) => ({ person: p, h: 20, lines: LINES.groundCrew })),
        ...spotters.people.map((p) => ({ person: p, h: 20, lines: LINES.spotters })),
      ],
    },
  };

  function mountScene(el) {
    const config = SCENES[el.dataset.live];
    if (!config) return;

    const canvas = document.createElement("canvas");
    canvas.className = "scene-canvas";
    canvas.setAttribute("aria-hidden", "true");
    const ctx = canvas.getContext("2d");
    const view = { ctx, cam: 0, viewW: 720 };
    const traffic = createTraffic({ ...config.traffic, levelW: 720 });
    const crowd = createCrowd(config.crowd);
    const spotters = config.spotters ? createCrowd({ sheet: "crew", rows: 3, standers: config.spotters }) : null;
    const stand = config.stand ? createStand(config.stand) : null;
    const chatter = createChatter({ host: el, canvas, speakers: () => config.talk({ crowd, spotters, stand }) });
    let img = null;
    let last = 0;
    let visible = true;
    let scale = 2;

    function resize() {
      scale = Number(getComputedStyle(el).getPropertyValue("--s")) || 2;
      view.viewW = Math.min(720, Math.floor(el.clientWidth / scale));
      view.cam = Math.floor((720 - view.viewW) / 2);
      canvas.width = view.viewW;
      canvas.height = 168;
      canvas.style.width = `${view.viewW * scale}px`;
      canvas.style.height = `${168 * scale}px`;
      canvas.style.left = `${Math.floor((el.clientWidth - view.viewW * scale) / 2)}px`;
      ctx.imageSmoothingEnabled = false;
      draw();
    }

    function drawLayer(layer) {
      if (!layer.startsWith("@")) {
        ctx.drawImage(img[layer], view.cam, 0, view.viewW, 168, 0, 0, view.viewW, 168);
        return;
      }
      const [name, args = ""] = layer.slice(1).split(":");
      const [a, b, c, d] = args.split(",").map(Number);
      const now = performance.now();
      if (name === "planes") traffic.drawPlanes(view, img);
      else if (name === "crowd") crowd.draw(view, img);
      else if (name === "spotters") spotters.draw(view, img);
      else if (name === "beacon" && blinkOn(1400)) pixel(view, a, b, "#ff3b30");
      else if (name === "laptop") {
        ctx.globalAlpha = reduceMotion ? 0.7 : 0.5 + 0.4 * (Math.floor(now / 700) % 3) / 2;
        ctx.fillStyle = "#7fb2ff";
        ctx.fillRect(a - view.cam, b, c, d);
        ctx.globalAlpha = 1;
      } else if (name === "photographer") {
        sprite(view, img.photographer, reduceMotion ? 0 : Math.floor(now / 2000) % 2, 26, 62, a, b, false);
      } else if (name === "stand") {
        stand.draw(view, img);
      }
    }

    function draw() {
      if (!img) return;
      if (config.transparent) ctx.clearRect(0, 0, view.viewW, 168);
      config.layers.forEach(drawLayer);
    }

    function loop(now) {
      const dt = Math.min(0.05, (now - last) / 1000 || 0);
      last = now;
      if (!reduceMotion) {
        traffic.update(dt, view);
        crowd.update(dt);
        if (stand) stand.update(dt, view);
      }
      chatter.update(dt, view, scale);
      draw();
      if (visible) requestAnimationFrame(loop);
    }

    loadImages(config.images).then((loaded) => {
      img = loaded;
      el.prepend(canvas);
      el.classList.add("is-live");
      addEventListener("resize", resize);
      resize();
      if (reduceMotion) {
        traffic.freeze(view);
        if (stand) stand.freeze();
      }
      draw();
      new IntersectionObserver(([entry]) => {
        const was = visible;
        visible = entry.isIntersecting;
        if (visible && !was) {
          last = performance.now();
          requestAnimationFrame(loop);
        }
      }).observe(el);
      last = performance.now();
      requestAnimationFrame(loop);
    }).catch(() => {
      // Keep the static fallback scene if the art fails to load.
    });

    // Small hook for automated tests.
    el.sceneState = () => ({
      scale, viewW: view.viewW, cam: view.cam, canvasW: canvas.getBoundingClientRect().width,
      planes: traffic.planes.map(describePlane),
      people: crowd.people.length + (spotters ? spotters.people.length : 0),
      walkers: crowd.people.filter((p) => p.v).map((p) => Math.round(p.x)),
      line: chatter.line,
      ...traffic.stats,
      stand: stand && {
        phase: stand.state.phase, x: +stand.state.x.toFixed(2), tugX: stand.state.tugX === null ? null : +stand.state.tugX.toFixed(2),
        hooked: stand.state.hooked, livery: stand.state.livery, cycles: stand.state.cycles,
      },
    });
  }

  document.querySelectorAll("[data-live]").forEach(mountScene);

  return { PLANE_W, PLANE_H, reduceMotion, rand, loadImages, sprite, createTraffic, createCrowd, createChatter, describePlane, LINES };
})();
